#include "civ5/graphics/bnw_unit_vis_ini_source_serializer.hpp"
#include "civ5/graphics/bnw_unit_art_scale_source_fields.hpp"
#include <fstream>
#include <iostream>
#include <vector>
void require(bool v,const char* s){if(!v)throw std::runtime_error(s);}
int main(int argc,char**argv){try{require(argc==2,"Usage: ini-serializer fixture");std::ifstream f(argv[1],std::ios::binary);require(bool(f),"Fixture missing");std::vector<char> data((std::istreambuf_iterator<char>(f)),{});require(data.size()>=12&&std::string(data.data(),8)=="BNWINI01","Source fixture magic");std::size_t at=8;auto word=[&]{require(at+4<=data.size(),"Fixture extent");std::uint32_t value=0;for(unsigned i=0;i<4;++i)value|=std::uint32_t(static_cast<unsigned char>(data[at++]))<<(i*8);return value;};require(word()==4,"Closed source getter case count");for(unsigned n=1;n<=4;++n){auto bytes=word();require(at+bytes<=data.size(),"Fixture payload extent");const auto result=civ5::graphics::unit_art_scale_detail::missing_unit_vis_scale_ini(n);require(result==std::string(data.data()+at,bytes),"Original828280 serializer output differs");at+=bytes;const auto fields=civ5::graphics::unit_art_scale_detail::read_user_scale_fields(result);require(fields.scale==1.f&&fields.multiplier==1.f&&fields.scale_defaulted==(n==1)&&!fields.multiplier_defaulted&&fields.seed_defaulted==(n<3)&&fields.threaded_defaulted==(n<4)&&fields.seed==-1&&fields.threaded==1,"Retained source getters after serialization");}require(at==data.size(),"Trailing fixture data");unsigned negative=0;for(unsigned invalid:{0u,5u}){bool failed=false;try{(void)civ5::graphics::unit_art_scale_detail::missing_unit_vis_scale_ini(invalid);}catch(const std::exception&){failed=true;}require(failed,"Unknown source getter accepted");++negative;}std::cout<<"PASS 4 original serializer-walk byte outputs, "<<negative<<" refusals; pure bytes only, no user filesystem/parser receipt\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
